template:
use std::sync::mpsc;
use std::thread;

fn sum_two_threads() -> i32 {
    let (tx, rx) = mpsc::channel();
    let tx2 = tx.⟦slot1⟧;

    thread::spawn(move || {
        tx.send(10).unwrap();
    });

    thread::spawn(move || {
        tx2.send(20).unwrap();
    });

    ⟦slot2⟧ + rx.recv().unwrap()
}

fn main() {
    println!("{}", sum_two_threads());
}
